   ```javascript
   const { Client, GatewayIntentBits } = require('discord.js');
   const { readFileSync } = require('fs');
   const { join } = require('path');

   const client = new Client({
     intents: [
       GatewayIntentBits.Guilds,
       GatewayIntentBits.GuildMessages,
       GatewayIntentBits.MessageContent,
     ],
   });

   const commands = {
     ban: {
       data: {
         name: 'ban',
         description: 'Банит пользователя.',
         options: [
           {
             name: 'user',
             description: 'Пользователь, которого нужно забанить.',
             type: 6,
             required: true,
           },
           {
             name: 'reason',
             description: 'Причина банного действия.',
             type: 3,
             required: false,
           },
         ],
         permissions: ['BAN_MEMBERS'],
         defaultPermission: false,
       },
       execute: async (interaction) => {
         const member = interaction.options.getMember('user');
         const reason = interaction.options.getString('reason', true);

         if (!member) {
           return interaction.reply({
             content: 'Укажите пользователя для банирования.',
             ephemeral: true,
           });
         }

         if (member.permissions.has('BAN_MEMBERS')) {
           return interaction.reply({
             content: 'Невозможно забанить администратора.',
             ephemeral: true,
           });
         }

         await member.ban({
           reason: reason || 'Нет причины.',
         });

         return interaction.reply({
           content: `${member.user.tag} был забанен за ${reason || 'Нет причины.'}.`,
         });
       },
     },
   };

   const commandFiles = join(__dirname, 'commands');
   const command = {};

   (async () => {
     try {
       // Load commands
       const commandFiles = await readdir(commandFiles, { withFileTypes: true });
       for (const file of commandFiles.filter((file) => file.isFile() && file.name.endsWith('.js'))) {
         const filePath = join(commandFiles, file.name);
         const commandName = file.name.slice(0, -3);

         const commandModule = await import(filePath);
         command[commandName] = commandModule.default;
       }

       // Register commands
       client.application.commands.set(commands, { scope: interaction.guildId });

       console.log('Bot is ready!');

       client.login(process.env.TOKEN);
     } catch (error) {
       console.error(error);
     }
