```cpp
#include <iostream>
#include <string>

std::string convertToHtml(const std::string& inputText) {
    std::string htmlText;
    for (char c : inputText) {
        switch (c) {
            case '<':
                htmlText += "&lt;";
                break;
            case '>':
                htmlText += "&gt;";
                break;
            case '&':
                htmlText += "&amp;";
                break;
            case '"':
                htmlText += "&quot;";
                break;
            default:
                htmlText += c;
                break;
        }
    }
    return htmlText;
}

int main() {
    std::string inputText = "<h1>Hello, world!</h1>";
    std::string htmlText = convertToHtml(inputText);
    std::cout << htmlText << std::endl;  // Outputs: &lt;h1&gt;Hello, world!&lt;/h1&gt;
    return 0;
}
```

